-- 5. OPENING HOURS (6 dias por loja, segunda a sabado)
-- ============================================================
INSERT INTO OpeningHours (Id, StoreId, DayOfWeek, OpenHour, CloseHour)
SELECT UUID(), s.Id, d.n,
  CASE
    WHEN s.CategoryId = '10000000-0000-0000-0000-000000000004' THEN '07:00'
    WHEN s.CategoryId = '10000000-0000-0000-0000-000000000010' THEN '10:00'
    ELSE '08:00'
  END AS OpenHour,
  CASE
    WHEN d.n = 6 THEN '14:00'
    WHEN s.CategoryId = '10000000-0000-0000-0000-000000000010' THEN '20:00'
    WHEN s.CategoryId = '10000000-0000-0000-0000-000000000004' THEN '12:00'
    ELSE '18:00'
  END AS CloseHour
FROM Stores s
CROSS JOIN (
  SELECT 1 AS n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6
) d
WHERE s.CategoryId IN (
  '10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',
  '10000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000004',
  '10000000-0000-0000-0000-000000000005','10000000-0000-0000-0000-000000000006',
  '10000000-0000-0000-0000-000000000007','10000000-0000-0000-0000-000000000008',
  '10000000-0000-0000-0000-000000000009','10000000-0000-0000-0000-000000000010'
);

